using System.Text.Json.Nodes;
internal static class SafetyChecks {
 internal static async Task<int> Run(Func<JsonObject,string,Task<JsonNode>> call,string fixture){
  int count=0;void Check(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}bool Ok(JsonNode node)=>node["ok"]?.GetValue<bool>()==true;
  string key=File.ReadAllText(Path.Combine(fixture,"user/mods/LocalGearMail/api-key.txt")).Trim(),file=Directory.GetFiles(Path.Combine(fixture,"user/profiles"),"*.json").First();var profile=JsonNode.Parse(File.ReadAllText(file))!;var pmc=profile["characters"]!["pmc"]!;var inventory=pmc["Inventory"]!;var source=inventory["items"]!.AsArray();string root=inventory["equipment"]!.GetValue<string>();var ids=new HashSet<string>{root};bool changed;do{changed=false;foreach(var item in source)if(item?["parentId"] is JsonValue parent&&ids.Contains(parent.GetValue<string>()))changed|=ids.Add(item!["_id"]!.GetValue<string>());}while(changed);var tree=new JsonArray(source.Where(i=>ids.Contains(i!["_id"]!.GetValue<string>())).Select(i=>i!.DeepClone()).ToArray());
  string baseline=inventory.ToJsonString();JsonObject Request(string id)=>new(){["action"]="emergencyBackup",["apiKey"]=key,["id"]=id,["categories"]=new JsonArray("pmc"),["stashItems"]=tree.DeepClone()};
  Check(!Ok(await call(Request("000000000000000000000000"),"/local/gear/data")),"emergency backup rejects another character identity");var saved=await call(Request(pmc["_id"]!.GetValue<string>()),"/local/gear/data");Check(Ok(saved)&&saved["backup"]!.GetValue<string>().Length==32&&saved["sha256"]!.GetValue<string>().Length==64,"emergency equipment snapshot committed with SQLite hash receipt");Check(JsonNode.Parse(File.ReadAllText(file))!["characters"]!["pmc"]!["Inventory"]!.ToJsonString()==baseline,"emergency backup does not replace the live inventory");
  var bad=Request(pmc["_id"]!.GetValue<string>());bad["stashItems"]![0]!["_tpl"]="000000000000000000000000";Check(!Ok(await call(bad,"/local/gear/data")),"unknown emergency template rejected");
  var list=await call(new(){["action"]="backupList",["apiKey"]=key},"/local/gear/data");Check(list["backups"]!.AsArray().Any(b=>b?["Id"]?.GetValue<string>()==saved["backup"]!.GetValue<string>()||b?["id"]?.GetValue<string>()==saved["backup"]!.GetValue<string>()),"emergency snapshot appears in the normal restore list");return count;
 }
}
